public class ReportesActivity extends AppCompatActivity{DBHelper db;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_reportes);db=new DBHelper(this);cargar();}void cargar(){((TextView)findViewById(R.id.tvTotalPlantas)).setText(String.valueOf(db.listarPlantas().size()));((TextView)findViewById(R.id.tvTotalRiegos)).setText(String.valueOf(db.totalRiegos()));List<String> m=db.masRegadas();((TextView)findViewById(R.id.tvMasRegadas)).setText(m.isEmpty()?"Sin datos todavía.":TextUtils.join("\n",m));List<String> p=db.pendientes();((TextView)findViewById(R.id.tvPendientes)).setText(p.isEmpty()?"Todo está al día. 🌿":TextUtils.join("\n",p));RecyclerView rv=findViewById(R.id.recyclerHistorial);rv.setLayoutManager(new LinearLayoutManager(this));ArrayAdapter<String>a=new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,db.historialNombres()){public View getView(int pos,View cv,android.view.ViewGroup parent){TextView v=(TextView)super.getView(pos,cv,parent);v.setTextColor(getResources().getColor(com.ecoriego.app.R.color.eco_text));v.setPadding(0,12,0,12);return v;}};rv.setAdapter(new RecyclerView.Adapter<VH>(){public VH onCreateViewHolder(ViewGroup p,int v){TextView t=new TextView(p.getContext());t.setTextSize(13);t.setTextColor(getResources().getColor(R.color.eco_text));t.setPadding(0,12,0,12);return new VH(t);}public void onBindViewHolder(VH h,int i){h.t.setText(db.historialNombres().get(i));}public int getItemCount(){return db.historialNombres().size();}});}static class VH extends RecyclerView.ViewHolder{TextView t;VH(View v){super(v);t=(TextView)v;}}}
